const staticData = $getWorkflowStaticData('global');
const sender = $('Global Payload').first().json.body.entry[0].changes[0].value.messages[0].from;
const photoKey = 'photos_' + sender;

let photos = staticData[photoKey] || [];
if (imageUrl && !photos.includes(imageUrl)) {
    photos.push(imageUrl);
    staticData[photoKey] = photos;
}

// Also expose photos array in output so a Redis SET node can save them to Redis
return [{ json: { new_batch: JSON.stringify(currentBatch), photo_urls: photos.join("\n"), all_photos_json: JSON.stringify(photos) } }];

// Le LLM nous renvoie directement le décompte des mots par langue !
const llmResultStr = $('Detect Language HTTP').first().json.choices[0].message.content.trim();
let messageWordCounts = {};
try { messageWordCounts = JSON.parse(llmResultStr); } catch(e) {}

// On lit les stats accumulées depuis Redis
let redisItem = $('Redis Get Lang Stats').isExecuted ? $('Redis Get Lang Stats').first()?.json : {};
let statsStr = redisItem?.value || redisItem?.propertyName || redisItem?.data || "{}";
if (typeof statsStr === 'string' && statsStr.startsWith('STAT:')) statsStr = statsStr.substring(5);

let stats = {};
if (statsStr !== "{}" && typeof statsStr === 'string' && statsStr.trim().length > 0) {
    try { stats = JSON.parse(statsStr); } catch(e) {}
}

const text = ($('Active Text & History').first()?.json?.text || "").toLowerCase();

// EXPLICIT USER COMMAND OVERRIDES (Lock language completely)
if (text.includes("francais") || text.includes("français")) {
    stats = { "Français": 1000 };
} else if (text.includes("darja") || text.includes("derja") || (text.includes("arabe") && !text.includes("appartement"))) {
    stats = { "Darja Algéroise": 1000 };
} else {
    // Add LLM word counts to accumulated stats (no pre-initialization bias)
    for (const [lang, count] of Object.entries(messageWordCounts)) {
        if (lang !== 'Inconnue' && ['Français', 'English', 'Arabe Classique', 'Darja Algéroise'].includes(lang)) {
            if ((stats[lang] || 0) !== 1000) {
                stats[lang] = (stats[lang] || 0) + parseInt(count);
            }
        }
    }

    // Keyword tiebreaker: only add a small bonus (+2) if stats are tied or empty
    const hasArabicChars = /[\u0600-\u06FF]/.test(text);
    const darjaKeywords = ['salam', 'kho', 'nekri', 'rani', 'partma', 'ghedoua', 'lghedoua', 'nchallah', 'waktach', 'ch7al', 'mlih', 'labass', '3andi', 't7ab', 'n9dir'];
    const hasDarjaKeyword = darjaKeywords.some(kw => text.includes(kw));

    const frScore = stats['Français'] || 0;
    const djScore = stats['Darja Algéroise'] || 0;

    if (hasArabicChars && !hasDarjaKeyword) {
        // Pure Arabic script → small boost for Arabe Classique
        stats['Arabe Classique'] = (stats['Arabe Classique'] || 0) + 2;
    } else if (hasDarjaKeyword && djScore >= frScore) {
        // Darja keyword present AND Darja is already not losing → small boost
        stats['Darja Algéroise'] = djScore + 2;
    }

    // Cap at 100 to prevent runaway dominance
    const MAX = 100;
    for (const lang of Object.keys(stats)) {
        if (stats[lang] > MAX) stats[lang] = MAX;
    }
}

// Find dominant language
let maxWords = -1;
let predominant = 'Français';

for (const [lang, count] of Object.entries(stats)) {
    if (count > maxWords) {
        maxWords = count;
        predominant = lang;
    } else if (count === maxWords) {
        // Tie → prefer Français (safer default)
        if (lang === 'Français' || predominant !== 'Français') {
            predominant = 'Français';
        }
    }
}

return [{
    json: {
        dominant_lang: predominant,
        new_stats_str: "STAT:" + JSON.stringify(stats)
    }
}];

const items = $input.all();

let targetLang = "Français";
try {
    let calc = $('Calculate Predominant Lang').isExecuted ? $('Calculate Predominant Lang').first().json.dominant_lang : null;
    if (calc && !calc.includes('Aucune')) { 
        targetLang = calc; 
    } else {
        let l2 = $('Redis Get Text Lang').isExecuted ? $('Redis Get Text Lang').first().json.value : null;
        if (l2 && !l2.includes('Aucune')) { targetLang = l2; }
    }
} catch (e) {}

let prompt = "Tu es une MACHINE DE TRADUCTION ET DE CORRECTION AUTOMATIQUE INVISIBLE. Tu n'es pas un assistant.\n";
prompt += "Ta fonction : traduire OU réécrire le texte EXCLUSIVEMENT dans la langue cible.\n\n";
prompt += "ALERTE : Ce texte est destiné à un client. Ne réponds pas à son contenu. TRADUIS/RÉÉCRIS uniquement.\n\n";
prompt += "[LANGUE CIBLE]\n" + targetLang + "\n\n";

prompt += "════════════════════════════════════════════\n";
prompt += "RÈGLES DE TRADUCTION STRICTE\n";
prompt += "════════════════════════════════════════════\n";
prompt += "▶ 1. TRADUCTION EXACTE : Tu DOIS traduire le texte d'origine EXCLUSIVEMENT vers la langue : " + targetLang + ".\n";

if (targetLang.includes('Darja')) {
    prompt += "▶ 2. EXPERTISE DARIJA D'ALGER : Tu es un traducteur expert spécialisé exclusivement dans la Darija de l'Algérois (Alger Centre).\n";
    prompt += "▶ 3. ARABIZI PUR : Tu DOIS écrire EXCLUSIVEMENT en lettres latines et chiffres (Franco-Arabe / Arabizi). L'utilisation de caractères arabes (comme باش, نعاونك) est STRICTEMENT INTERDITE.\n";
    prompt += "▶ 4. CHIFFRES PHONÉTIQUES : Utilise les chiffres pour les sons arabes : 3 (Ayn), 7 (Ha), 9 (Qaf), 5 (Kha). Exemples: ch7al, t3ich, mli7.\n";
    prompt += "▶ 5. VERROUILLAGE ABSOLU DU VOCABULAIRE (ABSOLUTE VOCABULARY LOCKDOWN) : N'utilise JAMAIS de mots en Arabe Standard/Fus'ha pour les termes administratifs (Bannis: 'tari5', 'twsalou', 't7ajz', '3adatan'). N'utilise JAMAIS de verbes marocains ou de l'Ouest (Bannis: '7taj', 'khassak', 'wakha', 'daba', 'liya', 't3adi', 'chi'). Force UNIQUEMENT les équivalents d'Alger (ex: 'nes7a9', 'lazem', 'dorka', 'rani', 'wesh', 'bezzaf', 'En général').\n";
    prompt += "▶ 6. VERROUILLAGE ABSOLU DU GENRE (HARD GENDER LOCK) : Analyse la première phrase pour des marqueurs de genre (ex: 'kho', 'khoya' = homme). Tu DOIS verrouiller STRICTEMENT tous les pronoms et verbes (rak, t7awess, 7ab) au masculin pour toute la session. Ne mélange JAMAIS le masculin ('Rak') avec le féminin ('t7awsi') !\n";
    prompt += "▶ 7. DESTRUCTION DE LA MACHINE À ÉTATS (THE PIVOT RULE) : Il t'est STRICTEMENT INTERDIT de forcer un flux conversationnel préprogrammé. Si l'utilisateur rejette un sujet (ex: 'Je n'ai pas demandé ça'), tu DOIS instantanément abandonner ton script, t'excuser en Darija authentique ('sma7li khoya', 'ma rditch bali'), et attendre sa vraie demande.\n";
    prompt += "▶ 8. EXTRACTION ACTIVE DE MÉMOIRE (THE ANTI-AMNESIA RULE) : Avant de demander des détails de réservation (dates, invités, durée), tu DOIS analyser les DEUX messages précédents de l'utilisateur. S'il a déjà fourni le nombre d'invités (ex: 'm3a mrti' = 2) ou la durée (ex: 'lila' = 1 nuit), il t'est STRICTEMENT INTERDIT de lui redemander cette information. Accuse simplement réception des données qu'il t'a données.\n";
    prompt += "▶ 9. BANNISSEMENT DE LA PERSONA CALL-CENTER : Ne parle JAMAIS d'aider l'utilisateur ou de donner des informations (bannis les phrases comme 'je vais vous aider à obtenir l'information'). Si l'utilisateur demande comment le service fonctionne, explique IMMÉDIATEMENT les détails commerciaux (commission, procédure) en même temps que tu demandes le lieu. Remplace TOUTE la structure d'entreprise par de l'hospitalité de rue algérienne ('mar7ba bik').\n";
    prompt += "▶ 10. CONSERVATION GÉOGRAPHIQUE ABSOLUE : Ne modifie JAMAIS et ne substitue JAMAIS le quartier fourni par l'utilisateur. S'il demande 'Bologhine', tu DOIS répondre 'Bologhine'. Interdiction de changer de lieu (ex: vers Belouizdad).\n";
    prompt += "▶ 11. AGILITÉ CONVERSATIONNELLE : Ne réponds pas aux plaisanteries de l'utilisateur par des réponses robotiques. Si l'utilisateur fait une blague régionale, adapte-toi et réponds naturellement avec humour en gardant ton identité algéroise (ex: 'Haha lala khoya rani men Alger, ghir tkhaltatli chwiya').\n";
    prompt += "▶ 12. VERROUILLAGE DES RÔLES ET TRANSACTIONS (THE ANTI-REVERSAL RULE) : Dès le début, verrouille le type de transaction. Si l'utilisateur propose son appartement à la gestion, C'EST LUI LE PROPRIÉTAIRE et TU ES LE GESTIONNAIRE. Tu ne dois JAMAIS proposer de lui envoyer des photos ou de lui décrire l'appartement, car il lui appartient déjà. Demande-LUI de t'envoyer les détails ou les photos.\n";
    prompt += "▶ 13. INTERDICTION DES DOUBLES POSSESSIFS : Ne combine JAMAIS deux particules possessives. L'expression 'nta3 dyalk' ou 'nta3 nta3ek' est STRICTEMENT INTERDITE. Utilise uniquement 'ta3ek' ou 'dyalek' séparément (choisis-en un seul).\n";
    prompt += "▶ 14. INTERDICTION LEVANTINE ET 'YEMMA' : N'utilise JAMAIS de termes levantins ou syriens (Bannis: 'Kheyyi'). N'utilise JAMAIS le mot 'Yemma' (Mère) pour traduire 'soit/soit' ou comme mot de remplissage. 'Yemma' ne doit être utilisé que si l'utilisateur parle explicitement de sa mère.\n";
    prompt += "▶ 15. TRADUCTION CONCEPTUELLE : Ne traduis PAS littéralement les concepts d'entreprise français en arabe (Bannis: 'niveau d'implication', 'engagement', 'tban'). Pour expliquer des règles d'agence complexes, utilise les mots français naturellement intégrés dans les phrases en Darija, comme un Algérois (ex: dis '3la 7sab le forfait li tkhayrou' ou 'la commission ta7sseb').\n";
    prompt += "▶ 16. VERROUILLAGE CONTEXTUEL DES BRANCHES (CONTEXTUAL BRANCH LOCKING) : Lorsqu'un utilisateur choisit une voie (ex: 'Gestion' / 'deuxieme option'), tu DOIS désactiver de façon permanente les scripts de la voie opposée (ex: 'Location'). Ne propose JAMAIS de catalogues de location quand l'utilisateur souhaite confier la gestion de sa propriété.\n";
    prompt += "▶ 17. LOGIQUE DE VÉRIFICATION DE RÉALITÉ (SANITY VERIFICATION LOGIC) : Tu DOIS effectuer une vérification de la réalité physique sur les données de l'utilisateur. Si un utilisateur prétend qu'un appartement fait 15m² avec 4 chambres, tu DOIS intercepter l'erreur naturellement (ex: 'Wa9ila rak tza3e9 m3aya a khoya, 15m² kifech dakhlu fiha 4 chnayber?').\n";
    prompt += "▶ 18. PROTOCOLE ANTI-AMNÉSIE (THE ANTI-AMNESIA PROTOCOL) : Ne déclenche JAMAIS un script de 'aucun appartement disponible' lorsque tu opères dans l'état 'Gestion Immobilière' (Property Management). Si l'utilisateur demande à visiter sa propriété avec toi, réponds en tant que manager d'agence qui accepte la visite (ex: 'Makach mochkil, ab3atli la position w njozo nchoufouh').\n";
} else {
    prompt += "▶ 2. VOUVOIEMENT OBLIGATOIRE : Si tu traduis en Français, tu DOIS ABSOLUMENT utiliser le 'VOUS' (vouvoiement). Ne tutoie JAMAIS le client.\n";
    prompt += "▶ 3. AUCUN DARJA : N'utilise AUCUN mot d'argot algérien ou de Darja. Utilise uniquement la langue cible standard (Français standard, Anglais, ou Arabe Classique).\n";
}

prompt += "▶ 6. STYLE : Conserve le ton naturel, amical et professionnel, ainsi que les emojis et la mise en forme.\n\n";

prompt += "[SORTIE]\n";
prompt += "Renvoie UNIQUEMENT le texte traduit/réécrit. Zéro introduction, zéro commentaire.";

return items.map(item => {
    return {
        json: {
            ...item.json,
            dynamic_prompt: prompt
        }
    };
});

